    def create_pipeline(self, name: str, stages: list[dict]) -> int:
        # ... docstring ...
        # Validate DAG: detect cycles via topological sort
        stage_names = {s["name"] for s in stages}
        adj: dict[str, list[str]] = {s["name"]: s.get("depends_on", []) for s in stages}
        # Also validate deps reference existing stages
        for sname, deps in adj.items():
            for d in deps:
                if d not in stage_names:
                    raise ValueError(f"Stage '{sname}' depends on unknown stage '{d}'")
        visited: set[str] = set()
        in_stack: set[str] = set()
        def _dfs(node: str) -> None:
            if node in in_stack:
                raise ValueError(f"Circular dependency detected involving stage '{node}'")
            if node in visited:
                return
            in_stack.add(node)
            for dep in adj[node]:
                _dfs(dep)
            in_stack.discard(node)
            visited.add(node)
        for s in stage_names:
            _dfs(s)
