Add a claimer verification check inside complete_work:

    @_retry_on_busy
    def complete_work(self, work_id: int, result: dict) -> None:
        """Mark a work item as completed with a JSON result."""
        now = time.time()
        with self._lock:
            row = self._conn.execute(
                "SELECT claimed_by, status FROM work_queue WHERE id = ?",
                (work_id,),
            ).fetchone()
            if row is None:
                raise ValueError(f"Work item {work_id} not found")
            if row["status"] != "claimed":
                raise ValueError(f"Work item {work_id} is not claimed (status={row['status']})")
            if row["claimed_by"] != self.team:
                raise PermissionError(
                    f"Work item {work_id} is claimed by '{row['claimed_by']}', not '{self.team}'"
                )
            self._conn.execute(
                "UPDATE work_queue SET status = 'completed', result = ?, completed_at = ? WHERE id = ?",
                (json.dumps(result), now, work_id),
            )
            self._conn.commit()

        _bus_notify(self.bus_dir, "global", self.agent_id, self.team, {
            "event": "work-completed",
            "work_id": work_id,
        })

