Use a single lock acquisition and batch query:

    @_retry_on_busy
    def check_stage_ready(self, pipeline_id: int, stage_name: str) -> bool:
        """Check whether all dependencies for a stage are completed."""
        with self._lock:
            row = self._conn.execute(
                "SELECT depends_on FROM pipeline_stages WHERE pipeline_id = ? AND stage_name = ?",
                (pipeline_id, stage_name),
            ).fetchone()
            if row is None:
                return False
            deps = json.loads(row["depends_on"])
            if not deps:
                return True
            placeholders = ",".join("?" for _ in deps)
            count_row = self._conn.execute(
                f"SELECT COUNT(*) FROM pipeline_stages WHERE pipeline_id = ? AND stage_name IN ({placeholders}) AND status = 'completed'",
                (pipeline_id, *deps),
            ).fetchone()
            return count_row[0] == len(deps)
